(()=>{
const video='data:video/webm;base64,';
const attack='assets/meepo/meepo_attack_hq.ogg?v=2';
const poof='assets/meepo/meepo_poof_hq.ogg?v=2';
window.MeepoMedia={video,attack,poof};
window.playMeepoPoof=()=>{try{const a=new Audio(poof);a.volume=.9;a.play().catch(()=>{})}catch(_){}};
const old=window.playAttackSound;
if(typeof old==='function')window.playAttackSound=function(h){if(h?.id==='meepo'){try{const a=new Audio(attack);a.volume=.9;a.play().catch(()=>{})}catch(_){}return}return old.apply(this,arguments)};
})();